/// Remembers which language the app was told to use.
///
/// Holds a language tag — `en`, `ru` — rather than one of the app's locale
/// values, because the enum is generated by slang and lives above this layer.
/// Whichever tag comes back is matched against the languages this build
/// actually ships before anything is done with it, so a tag written by a build
/// that shipped one more of them cannot leave the app in a language it has no
/// strings for.
///
/// A device preference, like the theme beside it: which language a phone is
/// read in is a fact about the phone, not about the books kept on it.
abstract interface class LanguageStore {
  /// The tag last chosen, or null while the app is following the device.
  ///
  /// Never throws: an unreadable preference is the same as never having chosen,
  /// and the device's own language is the answer either way.
  Future<String?> read();

  /// Remembers [languageTag], or that the device is being followed when it is
  /// null.
  ///
  /// Never throws either.
  Future<void> write(String? languageTag);
}
